const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";

const [deep, vert, more] = await Promise.all([
  fs.readFile(S+"\\_GIG_DEEP_RESULT.json","utf8").then(JSON.parse).catch(()=>[]),
  fs.readFile(S+"\\_GIG_VERTICAL_RESULT.json","utf8").then(JSON.parse).catch(()=>[]),
  fs.readFile(S+"\\_GIG_MORE_RESULT.json","utf8").then(JSON.parse).catch(()=>[])
]);

const GOOD = /活多且带价|活多|有活|有价格/;
const seen = new Set();
const uniq = [];
for (const o of [...deep,...vert,...more]) {
  if (!GOOD.test(String(o.verdict))) continue;
  const h = String(o.host).toLowerCase().replace(/^www\./,"");
  if (seen.has(h)) continue;
  seen.add(h);
  uniq.push({ name:o.name, host:h, url:o.url||("https://"+h), type:o.type||"", verdict:String(o.verdict), cards:o.cards||0, money:o.moneyMentions||0 });
}
// 按信号强度排序
const score = v => v.verdict.includes("活多且带价")?3: v.verdict.includes("活多")?2: v.verdict.includes("有活")?1:0;
uniq.sort((a,b)=>score(b)-score(a) || b.cards-a.cards);

await fs.writeFile(S+"\\_GIG_ALL_ALIVE.json", JSON.stringify(uniq,null,1), "utf8");
return { total: uniq.length, list: uniq.map((u,i)=>(i+1)+". "+u.name+" ["+u.verdict+"] cards="+u.cards) };
